import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import 'request_providers.dart';class CreateRequestScreen extends ConsumerStatefulWidget{const CreateRequestScreen({super.key,this.serviceId,this.providerId});final String? serviceId,providerId;@override ConsumerState<CreateRequestScreen>createState()=>_CreateState();}class _CreateState extends ConsumerState<CreateRequestScreen>{final form=GlobalKey<FormState>();final name=TextEditingController(),phone=TextEditingController(),email=TextEditingController(),message=TextEditingController();bool loading=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('New request')),body:Form(key:form,child:ListView(padding:const EdgeInsets.all(20),children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'Name'),validator:(v)=>v==null||v.isEmpty?'Name required':null),TextFormField(controller:phone,decoration:const InputDecoration(labelText:'Phone'),validator:(v)=>v==null||v.isEmpty?'Phone required':null),TextFormField(controller:email,decoration:const InputDecoration(labelText:'Email (optional)'),validator:(v)=>v!=null&&v.isNotEmpty&&!v.contains('@')?'Invalid email':null),TextFormField(controller:message,maxLines:5,decoration:const InputDecoration(labelText:'Message'),validator:(v)=>v==null||v.isEmpty?'Message required':null),const SizedBox(height:20),FilledButton(onPressed:loading?null:()async{if(!form.currentState!.validate())return;setState(()=>loading=true);try{await ref.read(requestRepoProvider).create({'name':name.text,'phone':phone.text,'email':email.text.isEmpty?null:email.text,'message':message.text,'service_id':widget.serviceId,'provider_id':widget.providerId});if(c.mounted){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Request submitted successfully')));c.go('/requests');}}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>loading=false);}},child:Text(loading?'Submitting…':'Submit request'))])));}
